/**
 * The facts per Dutch municipality behind /nl/noodplan/<gemeente>/.
 * The JSON is generated by handbook/scripts/gemeenten.mjs; the broadcaster
 * table is shared with the handbook (handbook/data/regions-nl.json).
 */
import data from './gemeenten-nl.json';
import regions from '../../handbook/data/regions-nl.json';

export interface Seh {
  name: string;
  place: string;
  allDay: boolean;
  km: number;
}

export interface Gemeente {
  code: string;
  name: string;
  slug: string;
  province: string | null;
  centre: { lat: number; lon: number; place: string };
  region: string | null;
  broadcaster: string | null;
  regionWebsite: string | null;
  waterBoards: string[];
  seh: Seh[];
  flood: { sampled: number; inZone: number; types: string[] };
  level: { n: number; min: number; max: number; median: number } | null;
  neighbours: string[];
}

export const gemeenten = data.gemeenten as Gemeente[];
export const checked = data.checked as string;
export const bySlug = new Map(gemeenten.map((g) => [g.slug, g]));

type Broadcaster = { fm: string[][]; dab: string };
export const broadcasters = regions.broadcasters as Record<string, Broadcaster>;

/** 3.4 -> "3,4" */
export const nl = (n: number, digits = 1) => n.toLocaleString('nl-NL', { minimumFractionDigits: digits, maximumFractionDigits: digits });

/** "ligt op 2,1 m boven NAP" style wording for a level. */
export const nap = (v: number) => `${nl(Math.abs(v))} m ${v < 0 ? 'onder' : 'boven'} NAP`;

/** One sentence on the flood-risk sample. */
export function floodSentence(g: Gemeente): string {
  const { sampled, inZone } = g.flood;
  if (!sampled) return `Voor ${g.name} konden we het overstromingsrisico niet bepalen.`;
  if (inZone === 0) return `Geen van de ${sampled} meetpunten bij woningen in ${g.name} ligt in een aangewezen overstromingsrisicogebied.`;
  if (inZone === sampled) return `Alle ${sampled} meetpunten bij woningen in ${g.name} liggen in een aangewezen overstromingsrisicogebied.`;
  return `${inZone} van de ${sampled} meetpunten bij woningen in ${g.name} liggen in een aangewezen overstromingsrisicogebied.`;
}

/** Short answer for the fact tile. */
export function floodShort(g: Gemeente): string {
  const { sampled, inZone } = g.flood;
  if (!sampled) return 'Onbekend';
  if (inZone === 0) return 'Nee';
  if (inZone === sampled) return 'Ja, overal';
  return inZone / sampled >= 0.5 ? 'Grotendeels' : 'Deels';
}

const TYPE_TEXT: Record<string, string> = {
  A: 'onbeschermd langs het hoofdwatersysteem (buitendijks)',
  B: 'beschermd door dijken langs het hoofdwatersysteem',
  C: 'beschermd langs regionale wateren',
  D: 'onbeschermd langs regionale wateren',
};
/** "B: beschermd langs hoofdwatersysteem" -> readable phrase; unknown types pass through. */
export const floodType = (t: string) => TYPE_TEXT[t.split(':')[0]?.trim()] ?? t.replace(/^\w: /, '');
